create extension if not exists pgcrypto;create table if not exists profiles(id uuid primary key references auth.users(id),full_name text,role text default 'client',is_blocked boolean default false);create table if not exists businesses(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id),name text not null,category text,phone text,whatsapp text,address text,about text,theme text,status text default 'active');create table if not exists products(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id),name text,price numeric default 0);create table if not exists leads(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id),customer_name text,phone text,message text,status text default 'new');